<script>(function(){var r=document.getElementById('reactivos'),i=document.getElementById('implementos');function money(v){return '$'+(parseFloat(v)||0).toFixed(2)}function refresh(){document.getElementById('sum-reactivos').textContent=money(r.value);document.getElementById('sum-implementos').textContent=money(i.value);document.getElementById('sum-total').textContent=money((parseFloat(r.value)||0)+(parseFloat(i.value)||0))}r.addEventListener('input',refresh);i.addEventListener('input',refresh);refresh()}());</script>
